Parse Retell Payload:
// Retell tool-call webhook normalizer
//
// With `args_at_root: true` (the production-validated default), Retell sends
// LLM-extracted args SPREAD AT THE BODY ROOT — there is no `body.args` wrapper
// and no `body.call` object. Tool routing is via the `tool` HTTP header.
//
// This parser is defensive: it also still handles the older `args_at_root: false`
// shape (`body = { args: {...}, call: {...}, name: "..." }`) so flipping the
// tool flag back doesn't break anything.

const data = $input.first().json;
const headers = data.headers || {};
const body = data.body || {};

// Tool name — header-routed (preferred), fall back to body.name for legacy shape
const tool = headers.tool || body.name || '';

// Args — nested under body.args (args_at_root: false) OR spread at body root (args_at_root: true)
let args;
if (body.args && typeof body.args === 'object' && !Array.isArray(body.args)) {
    args = body.args;
} else {
    // Strip Retell-internal envelope fields; everything else is an arg.
    const { call, name, ...rootArgs } = body;
    args = rootArgs;
}


// Caller's number straight from Retell's own call metadata, when present.
// Under args_at_root:true there is no body.call, so this is usually null - but
// when it IS there it beats anything the model passes, because it cannot be
// forgotten or mistyped. "Validate: Flag Callback Args" already had a fallback
// reading a top-level callerPhone; until now nothing ever set it, so the field
// was dead code and callback emails went out reading "Phone: Unknown".
const callObj = body.call || data.call || {};
const callerPhone = callObj.from_number || callObj.fromNumber || null;

if (!tool) {
    return [{
        json: {
            tool: '',
            args: {},
            _parseError: 'No tool name found. Expected the `tool` HTTP header (set per-tool in the Retell agent config), or body.name for legacy webhook shape.'
        }
    }];
}

return [{ json: { tool, args, callerPhone } }];

Format: Services Response:
const servicesData = $('Wix: Query Services').first().json;
// Read the normalized args from Parse Retell Payload (handles args_at_root:
// true, where there is no body.args wrapper). Reading body.args directly off
// the raw webhook throws under args_at_root: true.
const args = $('Parse Retell Payload').first().json.args || {};
const serviceName = args.serviceName;
if (servicesData.message || servicesData.details || !servicesData.services) {
  return [{ json: { success: false, error: servicesData.message || 'Failed to retrieve services' } }];
}
const services = servicesData.services || [];
// 1. Map Pricing Variants
const pricingLookup = {};
try {
  const pricingItems = $('Wix: Get Pricing Variants').all();
  pricingItems.forEach(item => {
    const sv = item.json.serviceVariants || item.json;
    if (sv && sv.serviceId && sv.variants && sv.variants.values) {
      pricingLookup[sv.serviceId] = sv.variants.values.map(v => ({
        id: v.id,
        duration: v.choices?.[0]?.duration?.minutes + " min",
        price: "USD " + (v.price?.value || 0)
      }));
    }
  });
} catch (e) {
  console.error("Pricing map skipped or failed.");
}
// 2. Map Add-ons (Base Details Only: Name, Price, Duration)
const addOnLookup = {};
try {
  const addonItems = $('Wix: Get Add-ons').all();
  for (const item of addonItems) {
    const addon = item.json?.addOn || item.json;
    if (addon?.id) {
      addOnLookup[addon.id] = {
        name: addon.name || "Unknown",
        price: "USD " + (addon.price?.value || 0),
        duration: (addon.durationInMinutes || 0) + " min"
      };
    }
  }
} catch (e) {
  console.error("Error mapping Add-on base details:", e);
}
// 3. Final Lean Mapping (Extracts Group IDs directly from original data)
const formattedServices = services.map(s => {
  let availableAddOns = [];
  if (s.addOnGroups && s.addOnGroups.length > 0) {
    const localGroupMap = {};
    s.addOnGroups.forEach(group => {
      const groupId = group.id;
      const addOnIds = group.addOnIds || [];
      addOnIds.forEach(addOnId => {
        if (!localGroupMap[addOnId]) {
          localGroupMap[addOnId] = [];
        }
        if (!localGroupMap[addOnId].includes(groupId)) {
          localGroupMap[addOnId].push(groupId);
        }
      });
    });
    const uniqueIds = Object.keys(localGroupMap);
    availableAddOns = uniqueIds.map(id => {
      const details = addOnLookup[id] || {
        name: "Unknown",
        price: "USD 0",
        duration: "0 min"
      };
      return {
        id,
        name: details.name,
        price: details.price,
        duration: details.duration,
        groupIds: localGroupMap[id]
      };
    });
  }
  const isVaried = s.payment?.rateType === 'VARIED';
  const pricingVariants = isVaried ? pricingLookup[s.id] : undefined;
  const fixedPrice =
    !isVaried && s.payment?.fixed?.price?.value
      ? "USD " + s.payment.fixed.price.value
      : undefined;
  return {
    id: s.id,
    name: s.name,
    // Set to "request first" in Wix: a booking goes to the spa for approval.
    byRequest: s.onlineBooking?.requireManualApproval === true ? true : undefined,
    description: s.description,
    _locations: s.locations,
    price: fixedPrice,
    pricingVariants,
    availableAddOns: availableAddOns.length > 0 ? availableAddOns : undefined
  };
});

// 3b. V28 - drop non-bookable / demo entries.
// Wix sites ship default placeholder services (e.g. "30 min meeting") that carry
// no price and no pricing variants. The agent was reading these back to callers
// as if they were treatments. A real spa service always has a price, so filter on
// that rather than a hardcoded name blocklist - this stays correct when the client
// adds or renames services.
const bookableServices = formattedServices.filter(
  s => s.price || (Array.isArray(s.pricingVariants) && s.pricingVariants.length > 0)
);

// 4. Filter by serviceName if provided. Exact match first, then substring, so a
// loose partial can never shadow the intended service.
const normalizedInput = (serviceName || '').trim().toLowerCase();
let matchedServices = [];
if (normalizedInput) {
  matchedServices = bookableServices.filter(s => s.name.trim().toLowerCase() === normalizedInput);
  if (matchedServices.length === 0) {
    matchedServices = bookableServices.filter(s => s.name.toLowerCase().includes(normalizedInput));
  }
}

const finalServices = matchedServices.length > 0 ? matchedServices : bookableServices;

// 5. Shape the payload to the size of the question.
//
// V53 CHANGE - fixes the catalog silently arriving as {"success":true,"count":9}
// (call_d1fc46c0012c887c86f24ffdb3c, 2026-09-20, and every prod "what do you
// offer?" since 2026-09-14): Retell discards a tool result above a size cap
// that sits somewhere between the dev site's 11.8KB (7 services, delivered) and
// production's 19.4KB (9 services, dropped). With no names in front of it the
// model tried "Nicky" as a serviceName and then booked Deep Tissue for a caller
// who had never chosen a service.
//
// Per service the old payload was ~2.1KB, ~900 of it the business address
// under _locations, which nothing downstream reads. So:
//   catalog (no serviceName match) -> name, one-line description, price range.
//                                     ~250 bytes each. Enough to read the menu
//                                     and help someone choose.
//   detail  (serviceName matched)  -> everything the booking needs - variant
//                                     ids, add-ons - minus _locations. This is
//                                     the call step 2 makes for the chosen
//                                     service, so nothing the agent relied on
//                                     has moved.
const oneLine = (t) => (t || '').replace(/\s+/g, ' ').trim().slice(0, 140);
const priceSummary = (s) => {
  if (Array.isArray(s.pricingVariants) && s.pricingVariants.length) {
    return s.pricingVariants.map(v => `${v.duration} ${v.price}`).join(', ');
  }
  return s.price || '';
};

const catalog = matchedServices.length === 0;
const payload = finalServices.map(s => {
  if (catalog) {
    return { id: s.id, name: s.name, description: oneLine(s.description), pricing: priceSummary(s),
      ...(s.byRequest ? { byRequest: true } : {}) };
  }
  const { _locations, ...detail } = s;
  return { ...detail, description: oneLine(s.description) };
});

return [{ json: {
  success: true,
  count: payload.length,
  catalog,
  ...(catalog ? { note: 'Catalog view. Call again with serviceName for durations, prices, variant ids and add-ons.' } : {}),
  services: payload
} }];

Resolve: Service (Booking):
// Settle on ONE serviceId from the two signals the agent sends.
//
// The agent passes BOTH serviceName (what the caller actually said) and serviceId
// (a UUID it copied out of an earlier get_services response). The UUID is the
// fragile signal: across V24/V25/V26 the model repeatedly spliced a Frankenstein
// UUID out of a pricingVariant id or an add-on groupId, and Wix rejected it with
// an opaque error that dead-ended the caller.
//
// Order of trust:
//   1. Resolve serviceName against the live catalog (exact -> substring -> fuzzy).
//   2. Check whether the supplied serviceId actually exists in the catalog.
//   3. Prefer the NAME match - it reflects the caller's own words. Fall back to
//      the UUID only when the name cannot be resolved. If both fail, return an
//      actionable error listing real service names so the agent self-corrects.

const catalogRaw = $input.first().json;
const prev = $('Validate: Booking Args').first().json;
const args = Object.assign({}, prev.args || {});

// Upstream validation already failed - pass straight through.
if (prev._valid === false) {
    return [{ json: prev }];
}

const raw = Array.isArray(catalogRaw) ? catalogRaw[0] : catalogRaw;
const services = (raw && raw.services) || [];
const catalog = services
    .filter(s => s && s.id && s.name)
    .map(s => ({ id: s.id, name: String(s.name).trim() }));

const sentId = args.serviceId ? String(args.serviceId).trim() : null;

// Catalog call failed - trust whatever the agent sent, let Wix judge.
// Degrading to old behaviour beats a hard failure.
if (catalog.length === 0) {
    return [{ json: Object.assign({}, prev, { args,
        _serviceResolution: { source: 'catalog-unavailable', serviceId: sentId } }) }];
}

function norm(v) {
    return String(v || '').toLowerCase()
        .replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
}
const STOP = ['massage', 'min', 'mins', 'minute', 'session', 'the', 'a'];
function tokens(v) {
    return norm(v).split(' ').filter(t => t && STOP.indexOf(t) === -1);
}

const wanted = args.serviceName ? String(args.serviceName).trim() : null;
let resolved = null;
let how = 'none';
let ambiguousNames = null;

if (wanted) {
    const w = norm(wanted);

    resolved = catalog.find(s => norm(s.name) === w) || null;
    if (resolved) how = 'exact';

    if (!resolved) {
        const subs = catalog.filter(s => norm(s.name).indexOf(w) !== -1 || w.indexOf(norm(s.name)) !== -1);
        if (subs.length === 1) { resolved = subs[0]; how = 'substring'; }
        else if (subs.length > 1) { how = 'ambiguous'; ambiguousNames = subs.map(s => s.name); }
    }

    // token overlap with prefix tolerance - catches 'dip tissue', 'lymphatic drain'
    if (!resolved && how !== 'ambiguous') {
        const wt = tokens(wanted);
        if (wt.length) {
            let best = null, bestScore = 0;
            for (const s of catalog) {
                const st = tokens(s.name);
                if (!st.length) continue;
                const hits = wt.filter(t => st.some(x => x.slice(0, 4) === t.slice(0, 4))).length;
                const score = hits / Math.max(wt.length, st.length);
                if (score > bestScore) { bestScore = score; best = s; }
            }
            if (best && bestScore >= 0.5) { resolved = best; how = 'fuzzy'; }
        }
    }
}

const idEntry = sentId ? (catalog.find(s => s.id === sentId) || null) : null;
const idValid = !!idEntry;

let finalId = null, source = null, mismatch = false;

if (resolved) {
    finalId = resolved.id;
    source = 'serviceName:' + how;
    if (idValid && idEntry.id !== resolved.id) mismatch = true;
} else if (idValid) {
    finalId = idEntry.id;
    source = 'serviceId';
}

if (!finalId) {
    const names = catalog.map(s => s.name);
    let reason;
    if (how === 'ambiguous') {
        reason = 'serviceName "' + wanted + '" matches more than one service (' +
            ambiguousNames.join(', ') + '). Ask the caller which one they want.';
    } else if (sentId && !idValid) {
        reason = 'serviceId "' + sentId + '" is not a real service id' +
            (wanted ? ', and serviceName "' + wanted + '" could not be matched' : '') +
            '. Use the top-level id from get_services - not a pricingVariants id and not an add-on groupId.';
    } else {
        reason = 'Could not identify the service. Pass serviceName exactly as get_services returned it.';
    }
    return [{ json: Object.assign({}, prev, { args, _valid: false,
        _validationError: reason,
        _serviceResolution: { resolved: null, how, idValid, availableServices: names } }) }];
}

args.serviceId = finalId;
args.serviceName = (resolved || idEntry).name;

// "Request first" in Wix (Couples Massage since 2026-09-25): the booking must
// wait for the owner's approval - see "Wix: Confirm Booking".
const finalRaw = services.find(s => s && s.id === finalId) || {};
const requireManualApproval = !!(finalRaw.onlineBooking && finalRaw.onlineBooking.requireManualApproval === true);

return [{ json: Object.assign({}, prev, { args, _serviceResolution: {
    serviceId: finalId, serviceName: args.serviceName, source: source, how: how,
    sentServiceId: sentId, sentServiceIdValid: idValid, mismatch: mismatch,
    requireManualApproval } }) }];

Format: Booking Confirmation:
const confirmData = $input.first().json;
// Fallback to the create booking data if confirm had issues
const createData = $('Wix: Create Booking').first().json;

const booking = confirmData.booking || createData.booking || {};
const status = booking.status || '';

if (!booking.id) {
  return [{ json: { success: false, error: confirmData.message || 'Booking confirmation failed' } }];
}

// Confirm or Decline Booking (request-first services) declines when the slot was
// double-booked in the meantime - that is a failed booking, not a request.
if (status === 'DECLINED') {
  return [{ json: { success: false, bookingId: booking.id, status,
    error: 'That time was just taken, so it could not be booked. Call get_slots again and offer the caller another time.' } }];
}

// PENDING = a service set to "request first" in Wix: the owner still has to approve it.
const pending = status === 'PENDING';
const who = `${booking.contactDetails?.firstName} ${booking.contactDetails?.lastName}`;
const when = booking.bookedEntity?.slot?.startDate;

return [{ json: {
  success: true,
  confirmed: status === 'CONFIRMED',
  bookingId: booking.id,
  status,
  ...(pending ? { requested: true,
    note: 'This massage is booked by request - the spa has to approve it before it is confirmed. Tell the caller it is a request and the team will confirm it with them. Never say "you\'re all set".' } : {}),
  serviceId: booking.bookedEntity?.slot?.serviceId,
  contact: {
    firstName: booking.contactDetails?.firstName,
    lastName: booking.contactDetails?.lastName,
    phone: booking.contactDetails?.phone
  },
  message: pending ? `Request sent for ${who} on ${when} - waiting for the spa to approve it` : `Appointment booked for ${who} on ${when}`
} }];
